let modules=[];let day=0;let reviewed=[];try{reviewed=JSON.parse(localStorage.getItem('cv-reviewed')||'[]');if(!Array.isArray(reviewed))reviewed=[]}catch{}const el=id=>document.getElementById(id);function updateProgress(){el('progress').textContent=`${reviewed.length} / 8`;el('progress-bar').style.width=`${reviewed.length/8*100}%`}function render(){const query=el('search').value.trim().toLowerCase();const filtered=modules.filter(m=>(!day||Math.ceil(m.id/2)===day)&&(!query||[m.title,...m.topics].join(' ').toLowerCase().includes(query)));el('modules').replaceChildren();filtered.forEach((m,index)=>{const details=document.createElement('details');details.className='module';details.open=Boolean(query)||index===0;const summary=document.createElement('summary');for(const [cls,txt] of [['module-number',String(m.id).padStart(2,'0')],['module-title',m.title],['module-day',`DAY ${String(Math.ceil(m.id/2)).padStart(2,'0')}`],['plus','+']]){const span=document.createElement('span');span.className=cls;span.textContent=txt;summary.append(span)}details.append(summary);const body=document.createElement('div');body.className='module-body';const list=document.createElement('ul');m.topics.forEach(topic=>{const li=document.createElement('li');li.textContent=topic.replace(/\\\(|\\\)/g,'').replaceAll('C_v','Cv').replaceAll('K_v','Kv');list.append(li)});body.append(list);const label=document.createElement('label');label.className='review';const check=document.createElement('input');check.type='checkbox';check.checked=reviewed.includes(m.id);check.addEventListener('change',()=>{reviewed=check.checked?[...new Set([...reviewed,m.id])]:reviewed.filter(id=>id!==m.id);try{localStorage.setItem('cv-reviewed',JSON.stringify(reviewed))}catch{}updateProgress()});label.append(check,document.createTextNode('Mark outline as reviewed'));body.append(label);details.append(body);el('modules').append(details)});el('empty').hidden=filtered.length>0}fetch('course.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{modules=data;reviewed=reviewed.filter(id=>modules.some(m=>m.id===id));render();updateProgress()}).catch(()=>{el('modules').textContent='The curriculum could not load. Please reload or download the original syllabus.'});el('search').addEventListener('input',render);document.querySelectorAll('[data-day]').forEach(button=>button.addEventListener('click',()=>{day=Number(button.dataset.day);document.querySelectorAll('[data-day]').forEach(b=>b.classList.toggle('active',b===button));render()}));function response(x,type){if(type==='linear')return x;if(type==='quick')return Math.sqrt(x);return x===0?0:Math.pow(50,x-1)}function draw(){const travel=Number(el('travel').value);const type=el('characteristic').value;const value=response(travel/100,type);el('travel-value').textContent=travel;el('capacity').replaceChildren(document.createTextNode((value*100).toFixed(1)),Object.assign(document.createElement('small'),{textContent:'%'}));el('curve').setAttribute('d',Array.from({length:101},(_,i)=>`${i?'L':'M'}${50+i*4.2},${260-response(i/100,type)*240}`).join(' '));const x=50+travel*4.2,y=260-value*240;el('point').setAttribute('cx',x);el('point').setAttribute('cy',y);el('guide').setAttribute('d',`M50 ${y}H${x}V260`);el('characteristic-note').textContent={equal:'Each equal increment of travel produces an equal percentage change in flow capacity.',linear:'Equal increments of valve travel produce equal increments of flow capacity.',quick:'Capacity rises rapidly at low travel. This square-root curve is an illustration, not a manufacturer curve.'}[type]}el('travel').addEventListener('input',draw);el('characteristic').addEventListener('change',draw);draw();
